// Tariro_ide_idpte/src/cognitive_arch/explainable_predictive_models.rs

//! Defines data models for Tariro's Explainable & Trustworthy Predictive Modeling module,
//! including explainable predictions, transparency reports, and feature importance analyses.

use serde::{Serialize, Deserialize};
use chrono::{Utc, DateTime};
use std::collections::HashMap;

use crate::cognitive_arch::learning_models::VerificationStatus; // For verification statuses

/// A prediction generated by Tariro, accompanied by a detailed explanation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExplainablePrediction {
    pub id: String,
    pub prediction_target: String,
    pub predicted_outcome: String,
    pub confidence_score: f64, // 0.0 to 1.0
    pub explanation_summary: String,
    pub key_influencing_factors: Vec<String>,
    pub ethical_alignment: VerificationStatus, // New: Ethical alignment of the prediction
    pub data_reliability_score: f64, // New: Reliability of data used for prediction
    pub generated_at: DateTime<Utc>,
}

/// A detailed report detailing the internal logic and data path for a specific prediction.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TransparencyReport {
    pub id: String,
    pub prediction_id: String, // Link to ExplainablePrediction
    pub model_architecture_summary: String,
    pub data_sources_used: Vec<String>,
    pub reasoning_path: Vec<String>,
    pub ethical_bias_assessment: VerificationStatus, // New: Ethical bias assessment of the model logic
    pub security_integrity_audit: VerificationStatus, // New: Security audit of the prediction process
    pub generated_at: DateTime<Utc>,
}

/// Analysis quantifying the importance of various features in a predictive model.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct FeatureImportanceAnalysis {
    pub id: String,
    pub prediction_id: String,
    pub feature_importances: HashMap<String, f64>, // Feature name -> Importance score
    pub sensitivity_analysis_summary: String,
    pub ethical_proxy_detection: Vec<String>, // New: Detection of features acting as proxies for sensitive attributes
    pub security_tamper_detection: VerificationStatus, // New: Detection of tampering in feature data
    pub analyzed_at: DateTime<Utc>,
}

/// A report summarizing the audit of explainable predictive modeling processes.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PredictionAuditReport {
    pub id: String,
    pub scope: String, // e.g., "all_predictions", "critical_system_forecasts"
    pub period_start: DateTime<Utc>,
    pub period_end: DateTime<Utc>,
    pub total_predictions_generated: u64,
    pub explanations_validated: u64,
    pub detected_transparency_gaps: u64,
    pub ethical_compliance_status: VerificationStatus, // Overall ethical compliance of predictions
    pub security_integrity_status: VerificationStatus, // Overall security integrity of predictive systems
    pub blockchain_record_hash: String, // New: Tamper-proof hash from QR-CTFO
    pub generated_at: DateTime<Utc>,
}
